// React
import React, { useEffect } from "react";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";

// Redux
import { connect } from "react-redux";
import {
	fetchAffiliates,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
	deleteRegionCodes,
	addRegionCodes,
} from "../../../../actions/affiliates";
import { openModal } from "../../../../actions/utils";

// Components
import { Button, Card, CardBody, CardHeader, Col, Row, Table } from "reactstrap";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import AddRegion from "../../../../components/AddRegion";

const Region = ({
	// state from props
	allAffiliatesNamesAndCodes,
	regionCodes,
	regionCodesError,
	location                     : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	fetchAffiliates,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
	deleteRegionCodes,
	openModal,
}) => {
	useEffect(() => {
		fetchAffiliates();
		fetchAffiliatesNamesAndCodes();
		getRegionCodes();
	}, []);

	const RegionCodesTableHeader = [ "Code", "Affiliates", "Action" ];
	// create my copy of all affliates regions
	// Returns an array removing the "*" from the USD --> region.
	const AllAffiliateRegions = regionCodes
		? [ ...regionCodes ].map((region) => {
				region.affiliateCodes = region.affiliateCodes.filter((codes) => codes !== "*"); //filter off the "*" entry.
				return region;
			})
		: [];

	// create a custom copy of the All Names and Codes Array
	const AllAffiliateCodes = allAffiliatesNamesAndCodes
		? // Removes {label: "ALL", value: "ALL"} from the array passed to USD region.
			allAffiliatesNamesAndCodes.filter((nameAndCodes) => nameAndCodes.value !== "ALL")
		: [];
	AllAffiliateRegions.map((region) => {
		// loading only the affilate with the wildcard "*" which is USD
		if (region.code === "USD") {
			AllAffiliateCodes.map((aff) => {
				// this lines prevents this code from adding new affiliates when the component rerenders.
				if (region.affiliateCodes.length <= 32) {
					region.affiliateCodes = region.affiliateCodes.concat(aff.value);
				}
			});
		}
	});

	return (
		<div className='animated fadeIn'>
			<Row>
				<Col>
					<Card>
						<AddRegion />
						<CardHeader className={"d-flex justify-content-between align-items-center"}>
							<div className={"w-100 d-flex justify-content-between  align-items-center"}>
								<strong>
									<FormattedMessage id='Affiliate Regions' defaultMessage='Affiliate Regions' />
								</strong>

								{regionCodes && (
									<Button
										onClick={openModal}
										type='button'
										className={"float-right mb-0 btn-sm mx-1 "}
										color='success'
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-plus' />&nbsp;
											<FormattedMessage id='Add Region' defaultMessage='Add Region' />
										</span>
									</Button>
								)}
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!regionCodesError &&
							!regionCodes && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle Errors */}
							{!regionCodes &&
							regionCodesError &&
							regionCodesError.response &&
							regionCodesError.response.data && (
								<article className='d-flex justify-content-center align-items-center'>
									<p className='text-center text-danger'>
										<FormattedMessage
											id={regionCodesError.response.data.message}
											defaultMessage={regionCodesError.response.data.message}
										/>
									</p>
								</article>
							)}

							{regionCodes && (
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
								>
									<thead>
										<PostingTableHeader
											headerType={"array"}
											headerPayload={RegionCodesTableHeader}
										/>
									</thead>

									<tbody>
										{!regionCodesError &&
											AllAffiliateRegions.map((tableItem, index) => {
												return (
													<tr key={index}>
														<td>{tableItem.code}</td>
														<td>{tableItem.affiliateCodes.join(", ")}</td>
														<td
															className={
																"d-flex justify-content-start align-items-center"
															}
														>
															<Button
																type='button'
																className={"float-right mb-0 btn-sm mx-1 "}
																color='danger'
																onClick={() => deleteRegionCodes(tableItem.code)}
															>
																<FormattedMessage id='Delete' defaultMessage='Delete' />
															</Button>
														</td>
													</tr>
												);
											})}
									</tbody>
								</Table>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		fileSets                   : state.fileSets,
		allAffiliates              : state.affiliates,
		allAffiliatesNamesAndCodes : state.affiliates.affiliatesNamesAndCodes,
		regionCodes                : state.affiliates.region_codes,
		regionCodesError           : state.affiliates.region_codes_error,
	};
};

export default connect(mapStateToProps, {
	fetchAffiliates,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
	deleteRegionCodes,
	addRegionCodes,
	openModal,
})(Region);
