// React
import React, { useState } from "react";
import Select from "react-select";
import { FormattedMessage } from "react-intl";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";

// Components
import { addRegionCodes, fetchAffiliatesNamesAndCodes } from "../actions/affiliates";
import { closeModal } from "../actions/utils";
import { Button, Modal, ModalHeader, ModalFooter, Form, FormGroup, Label, Input, Col } from "reactstrap";

const AddRegion = (props) => {
	const { className, allAffiliatesNamesAndCodes, toggleModal, closeModal, addRegionCodes } = props;

	const [ regions, setRegions ] = useState("");
	const [ regionCodes, setRegionCodes ] = useState([]);

	const handleSelectRegion = (selectedOption) => setRegionCodes(selectedOption);

	// create a custom copy of the All Names and Codes Array
	// Removes {label: "ALL", value: "ALL"} from the array used.
	const AllAffiliateCodes =
		allAffiliatesNamesAndCodes && allAffiliatesNamesAndCodes.filter((nameAndCodes) => nameAndCodes.value !== "ALL");

	const handleSubmit = () => {
		if (regions.length === 0 || regionCodes.length === 0) {
			return;
		}

		let affiliateCodes = [];
		affiliateCodes = regionCodes.map((regionCode) => {
			return regionCode.value;
		});

		const newRegion = {
			affiliateCodes,
			code           : regions.toUpperCase(),
		};
		addRegionCodes(newRegion);
		closeModal();
	};

	return (
		<div>
			<Modal isOpen={toggleModal} className={className}>
				<ModalHeader>
					<FormattedMessage id='Add Region' defaultMessage='Add Region' />
				</ModalHeader>
				<Col xs={12}>
					<Form className={"d-flex flex-column justify-content-center py-3"}>
						<FormGroup>
							<Label for='RegionCode'>
								<FormattedMessage id='Region Code' defaultMessage='Region Code' />
							</Label>
							<Input
								type='RegionCode'
								name='RegionCode'
								id='RegionCode'
								placeholder='Enter Region Code'
								onChange={(e) => setRegions(e.target.value)}
							/>
						</FormGroup>

						<FormGroup>
							<span>Region Affiliate Codes</span>
							<Select
								className={"w-100 mt-1"}
								onChange={handleSelectRegion}
								defaultValue={regions}
								isMulti
								options={AllAffiliateCodes}
							/>
						</FormGroup>
					</Form>
				</Col>
				<ModalFooter>
					<Button color='success' type='button' onClick={handleSubmit}>
						<FormattedMessage id='Submit' defaultMessage='Submit' />
					</Button>{" "}
					<Button color='danger' onClick={closeModal}>
						<FormattedMessage id='Cancel' defaultMessage='Cancel' />
					</Button>
				</ModalFooter>
			</Modal>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		allAffiliatesNamesAndCodes : state.affiliates.affiliatesNamesAndCodes,
		regionCodesError           : state.affiliates.region_codes_error,
		toggleModal                : state.utils.openModal,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchAffiliatesNamesAndCodes,
			addRegionCodes,
			closeModal,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(AddRegion);
